from schema import final

final(12,1,'دنا دو رشته‌ای','diagram_label','در نمودار درصد بازهای یک دنا دو رشته‌ای، برابری A با T و G با C دیده می‌شود. این برابری را با مکمل‌بودن توضیح دهید. آیا از این برابری در مجموع دو رشته می‌توان برابری A و T در تک‌تک رشته‌ها را نتیجه گرفت؟','هر A یک رشته مقابل T رشتهٔ دیگر و هر G مقابل C قرار می‌گیرد؛ بنابراین در مجموع دو رشته شمار A=T و G=C است. این برابری الزاماً در یک رشتهٔ جداگانه برقرار نیست، زیرا ترتیب و شمار بازهای همان رشته می‌تواند نامتقارن باشد و رشتهٔ مکمل آن را جبران کند.', [('استدلال مکمل‌بودن و برابری در کل مولکول',0.5),('رد تعمیم الزامی به هر رشتهٔ جداگانه',0.5),('توضیح جبران توسط رشتهٔ مکمل',0.5)],image='diagrams/dna_bases.png',imageDescription='نمودار چهار ستون برای درصد A و T برابر ۲۰ و G و C برابر ۳۰ در مجموع دو رشتهٔ دنا.')
final(12,1,'مکمل‌بودن و پیوندهای دنا','fill_blank','در یک بخش سه‌جفت‌بازی دنا، بازهای یک رشته A–C–T هستند. با نوشتن بازهای دقیقاً روبه‌روی آن‌ها و در همان ترتیب مکانی، رشتهٔ مکمل .......... است. اگر هر جفت A–T دو و هر جفت G–C سه پیوند هیدروژنی داشته باشد، مجموع پیوندها در همین سه جفت .......... است؛ محاسبه را نیز بنویسید.','T–G–A؛ ۷ پیوند هیدروژنی (۲+۳+۲). ترتیب در این سؤال مکانی و روبه‌روی بازهای داده‌شده است، نه بازنویسی هر دو رشته در جهت یکسان.', [('مکمل T–G–A در ترتیب مکانی خواسته‌شده',0.5),('شمارش دو جفت A–T و یک جفت G–C',0.5),('مجموع هفت پیوند',0.5)])
final(12,1,'ساختار پروتئین','short','چرا تغییر یک آمینواسید ممکن است فعالیت پروتئین را کم کند، اما نمی‌توان گفت هر جایگزینی الزاماً آن را کاملاً غیرفعال می‌کند؟','تغییر آمینواسید می‌تواند بر برهم‌کنش‌ها و تاخوردگی، به‌ویژه جایگاه فعال یا بخش‌های مهم، اثر بگذارد. اثر به نوع جایگزینی و جایگاه آن وابسته است؛ برخی جایگزینی‌ها اثر اندک دارند، پس حکم غیرفعال‌شدن کامل برای همهٔ موارد درست نیست.', [('پیوند توالی و ساختار/کارکرد',0.5),('وابستگی اثر به نوع و محل و رد حکم همیشگی',0.5)])

final(12,2,'پیرایش رنا','true_false','درستی عبارت را تعیین و اصلاح کنید: «در همهٔ ژن‌های یوکاریوتی، هر نوکلئوتید رنای اولیه الزاماً در رنای پیک بالغ باقی می‌ماند.»','نادرست است. در ژن‌های دارای بخش‌های حذف‌شونده، پیرایش می‌تواند بخش‌هایی از رنای اولیه را حذف و بخش‌های باقی‌مانده را به هم متصل کند؛ بنابراین همهٔ نوکلئوتیدهای رونویس اولیه الزاماً باقی نمی‌مانند.', [('نادرست‌بودن',0.5),('حذف بخش‌های مشخص و اتصال باقی‌مانده در پیرایش',0.5)],truth=False)
final(12,2,'رمزه و پادرمزه','definition_comparison','رمزه و پادرمزه را از نظر مولکول حامل، نقش و رابطهٔ مکمل مقایسه کنید؛ چرا رمزهٔ پایان، آمینواسیدی به نام «پایان» ندارد؟','رمزه توالی سه‌نوکلئوتیدی رنای پیک است که در ترجمه خوانده می‌شود. پادرمزه در رنای ناقل و مکمل رمزهٔ مناسب است و به قراردادن آمینواسید متناظر کمک می‌کند. رمزهٔ پایان با عامل پایان‌دهنده شناخته می‌شود و به رهاشدن پلی‌پپتید می‌انجامد، نه افزوده‌شدن آمینواسید پایان.', [('رمزه در رنای پیک و پادرمزه در رنای ناقل',0.5),('مکمل‌بودن و نقش در قراردادن آمینواسید',0.5),('عامل پایان‌دهنده و نبود آمینواسید پایان',0.5)])
final(12,2,'بیان ژن و تمایز','essay','یاختهٔ عصبی و یاختهٔ ماهیچه‌ای یک فرد بسیاری از ژن‌های یکسان را دارند. توضیح دهید چگونه می‌توانند شکل و کارکرد متفاوت داشته باشند، بدون آنکه لازم باشد رمز ژنتیکی آن‌ها متفاوت باشد.','در دو نوع یاخته، مجموعهٔ ژن‌های فعال و میزان بیان آن‌ها می‌تواند متفاوت باشد. این تفاوت‌ها به ساخت مجموعه‌های متفاوت پروتئین و در نتیجه ساختار و کارکرد اختصاصی کمک می‌کند. معنای رمزه‌ها لازم نیست عوض شود؛ تفاوت در تنظیم استفاده از اطلاعات مشترک است.', [('تفاوت مجموعه/میزان بیان ژن‌ها',0.5),('ارتباط پروتئین‌های متفاوت با ساختار و کارکرد',0.5),('تفکیک تنظیم بیان از تغییر رمز ژنتیکی',0.5)])

final(12,3,'هم‌توانی','short','در صفتی فرضی، فرد ناخالص هر دو فرآوردهٔ قابل‌تشخیصِ دو دگره را هم‌زمان نشان می‌دهد؛ رخ‌نمود او حالت بینابینیِ دو فرد خالص نیست. این رابطهٔ دگره‌ها چه نام دارد و چه تفاوتی با بارزیت ناقص دارد؟','این وضعیت هم‌توانی است؛ اثر هر دو دگره در رخ‌نمود ناخالص به‌طور قابل‌تشخیص دیده می‌شود. در بارزیت ناقص، رخ‌نمود ناخالص نسبت به دو حالت خالص، حالت بینابینی دارد؛ هم‌زمان دیده‌شدن دو فرآورده را نباید الزاماً بینابینی دانست.', [('تشخیص هم‌توانی و دیده‌شدن اثر هر دو دگره',0.5),('مقایسه با رخ‌نمود بینابینی در بارزیت ناقص',0.5)])
final(12,3,'گروه خونی ABO','fill_blank','در الگوی معمول ABO، فرد AB دگره‌های .......... و .......... دارد. دو دگره در رخ‌نمود او .......... هستند؛ فرد O معمولاً ژن‌نمود .......... دارد.','IA و IB؛ هم‌توان؛ ii. نوشتن A و B با مشخص‌کردن دگره‌ها نیز پذیرفتنی است.', [('دو دگرهٔ IA و IB',0.5),('هم‌توانی',0.5),('ژن‌نمود ii',0.5)])
final(12,3,'احتمال وابسته به X','essay','مادری ناقل یک صفت نهفتهٔ وابسته به X و پدری سالم‌اند. احتمال ابتلا را یک‌بار در میان پسران و یک‌بار در میان همهٔ فرزندان محاسبه کنید؛ فرض کنید احتمال دو جنس برابر و جهش تازه‌ای رخ نمی‌دهد.','در میان پسران، یک‌دوم مبتلا می‌شوند، چون X آن‌ها از یکی از دو X مادر می‌آید. در میان همهٔ فرزندان، احتمال پسربودن یک‌دوم و احتمال دریافت X دارای دگرهٔ نهفته یک‌دوم است، پس احتمال ابتلای پسر یک‌چهارم است. دختران با X سالم پدر در این الگوی نهفته مبتلا نمی‌شوند، هرچند نیمی می‌توانند ناقل باشند.', [('احتمال شرطی یک‌دوم در پسران با دلیل X مادری',0.5),('ضرب دو احتمال و یک‌چهارم در کل',0.5),('عدم ابتلای دختران در فرض مسئله با X سالم پدر',0.5)])

final(12,4,'انتخاب طبیعی','true_false','درستی عبارت را تعیین و اصلاح کنید: «وجود پادزیست، باکتری را وادار می‌کند دگرهٔ مقاومتِ مورد نیاز خود را هدفمند بسازد.»','نادرست است. جهش‌ها برای پاسخ هدفمند به نیاز ایجاد نمی‌شوند. اگر مقاوم‌ها از پیش وجود داشته باشند، پادزیست با حذف نسبی حساس‌ها به بقا و تولیدمثل بیشتر مقاوم‌ها کمک می‌کند و فراوانی دگرهٔ مقاومت افزایش می‌یابد.', [('رد پیدایش هدفمند بر اثر نیاز',0.5),('بقای متفاوت و افزایش سهم مقاوم‌های موجود',0.5)],truth=False)
final(12,4,'جهش ژنی و عددی','matching','رویدادها را به توصیف مناسب وصل کنید: الف) حذف یک نوکلئوتید از بخش رمزکننده، ب) عدم جدایی همتاها در میوز اول، پ) ورود تصادفی چند بنیان‌گذار با فراوانی متفاوت دگره. توصیف‌ها: ۱) امکان تغییر تعداد یک فام‌تن در گامت، ۲) امکان جابه‌جایی چارچوب خواندن، ۳) نمونه‌ای از رانش دگره‌ای.','الف–۲؛ ب–۱؛ پ–۳.', [('حذف تک‌نوکلئوتیدی و تغییر چارچوب',0.5),('عدم جدایی و گامت کم/اضافه‌فام‌تن',0.5),('بنیان‌گذار و رانش',0.5)],promptParts=[{'id':'a','text':'حذف یک نوکلئوتید'},{'id':'b','text':'عدم جدایی همتاها'},{'id':'c','text':'بنیان‌گذاری تصادفی جمعیت'}])
final(12,4,'خطای میوز','essay','در میوز یک یاخته، همتاهای یک جفت در تقسیم نخست به یک قطب رفته‌اند؛ تقسیم دوم طبیعی است. چهار گامت را از نظر تعداد آن فام‌تن مقایسه کنید و توضیح دهید چرا تقسیم دوم خطا را جبران نمی‌کند.','دو گامت یک فام‌تن اضافه نسبت به n دارند و دو گامت یک فام‌تن کمتر. در تقسیم اول هر دو همتا وارد یک یاخته و هیچ‌یک وارد دیگری شده‌اند؛ جدایی طبیعی کروماتیدها در تقسیم دوم این توزیع نامساوی همتاها را اصلاح نمی‌کند.', [('دو n+1 و دو n−1',0.5),('توزیع هر دو همتا در یک یاخته و نبود در دیگری',0.5),('تمایز جدایی خواهری دوم از جدایی همتای اول',0.5)])

final(12,5,'تخمیر','fill_blank','در تخمیر لاکتیکی، تبدیل پیرووات به لاکتات با تبدیل NADH به .......... همراه است؛ این بازسازی به ادامهٔ .......... کمک می‌کند.','NAD+؛ گلیکولیز.', [('NAD+ یا ناقل اکسیدشده',0.5),('گلیکولیز',0.5)])
final(12,5,'شیب پروتون','essay','ماده‌ای راه نشت پروتون از غشای درونی میتوکندری باز می‌کند، بدون آنکه مستقیماً زنجیرهٔ انتقال الکترون را ببندد. چرا با وجود امکان جریان الکترون، ساخت ATP می‌تواند کم شود؟','زنجیرهٔ انتقال الکترون با انتقال پروتون اختلاف دو سوی غشا را ایجاد می‌کند. اگر پروتون‌ها از راه نشت و بدون عبور از ATPساز برگردند، شیب مؤثر کاهش می‌یابد و انرژی آن برای ATPسازی به‌خوبی به کار نمی‌رود. پس وجود جریان الکترون به‌تنهایی مقدار مناسب ATP را تضمین نمی‌کند.', [('نقش زنجیره در ایجاد شیب پروتون',0.5),('برگشت از مسیر نشت و کاهش شیب',0.5),('وابستگی ATPساز به شیب و تفکیک از صرف جریان الکترون',0.5)])
final(12,5,'جایگاه واکنش‌ها','matching','مرحله را به جایگاه معمول در یاختهٔ ماهیچه‌ای انسان وصل کنید: الف) گلیکولیز، ب) چرخهٔ کربس، پ) زنجیرهٔ انتقال الکترون تنفسی. جایگاه‌ها: ۱) غشای درونی میتوکندری، ۲) میان‌یاخته، ۳) بسترهٔ میتوکندری.','الف–۲؛ ب–۳؛ پ–۱.', [('گلیکولیز و میان‌یاخته',0.5),('کربس و بستره',0.5),('زنجیره و غشای درونی',0.5)],promptParts=[{'id':'a','text':'گلیکولیز'},{'id':'b','text':'چرخهٔ کربس'},{'id':'c','text':'زنجیرهٔ تنفسی'}])

final(12,6,'کلروپلاست','diagram_label','در شکل، A غشای تیلاکوئید و B بسترهٔ کلروپلاست است. دو فرآوردهٔ حامل انرژی/الکترون را که از واکنش‌های A در فرایندهای B مصرف می‌شوند بنویسید و بگویید اکسیژن آزادشده از کدام ماده منشأ می‌گیرد.','ATP و NADPH در واکنش‌های وابسته به نور فراهم می‌شوند و در چرخهٔ کالوینِ بستره مصرف می‌شوند. اکسیژن آزادشده در فتوسنتز اکسیژن‌زا از تجزیهٔ آب منشأ می‌گیرد، نه از کربن‌دی‌اکسید.', [('ATP و NADPH',1),('ارتباط واکنش نوری و چرخهٔ کالوین در دو جایگاه',0.5),('آب به‌عنوان منشأ اکسیژن',0.5)],image='diagrams/chloroplast.png',imageDescription='طرح کلروپلاست با غشای دوگانه و تیلاکوئیدها؛ A غشای تیلاکوئید و B بستره را مشخص می‌کند.')
final(12,6,'تنفس نوری','true_false','درستی عبارت را تعیین و اصلاح کنید: «بسته‌شدن روزنه‌های گیاه C3 در گرما فقط بر اتلاف آب اثر دارد و نسبت گازهای مؤثر بر روبیسکو را تغییر نمی‌دهد.»','نادرست است. بسته‌شدن روزنه ورود CO2 را محدود می‌کند و می‌تواند نسبت O2 به CO2 را افزایش دهد. در نتیجه احتمال واکنش روبیسکو با اکسیژن و تنفس نوری بیشتر و بازده تثبیت خالص کربن کمتر می‌شود.', [('رد محدودبودن اثر به آب',0.5),('محدودشدن CO2 و تغییر نسبت O2/CO2',0.5),('ارتباط با تنفس نوری و کاهش بازده',0.5)],truth=False)
final(12,6,'گیاه CAM','short','بازشدن عمدهٔ روزنه‌های گیاه CAM در شب چگونه به حفظ آب کمک می‌کند و کربن گرفته‌شده چگونه برای روز نگهداری می‌شود؟','شب معمولاً خنک‌تر است و بازبودن روزنه با اتلاف آب کمتری همراه می‌شود. کربن‌دی‌اکسید در ترکیبات آلی به‌طور موقت تثبیت و ذخیره می‌شود و روز برای چرخهٔ کالوین فراهم می‌شود؛ نیاز به نور در واکنش‌های نوری حذف نمی‌شود.', [('دریافت شبانه در شرایط با اتلاف کمتر آب',0.5),('تثبیت موقت در ترکیبات آلی و استفادهٔ روز',0.5)])

final(12,7,'کنترل PCR','short','چرا در کنار PCR نمونه، یک واکنش با همهٔ مواد لازم ولی بدون دنا الگو آماده می‌شود؟ مشاهدهٔ محصول در این شاهد چه اقدامی را ضروری می‌کند؟','شاهد بدون الگو برای آشکارکردن آلودگی یا محصول ناخواسته است. محصول در آن اعتبار نتیجه را تهدید می‌کند؛ باید احتمال آلودگی مواد یا واکنش ناخواسته بررسی و آزمایش با کنترل مناسب تکرار شود.', [('نقش شاهد منفی برای آلودگی/محصول ناخواسته',0.5),('لزوم بررسی و تکرار کنترل‌شده در صورت محصول',0.5)])
final(12,7,'اتصال دنا','fill_blank','پس از جفت‌شدن بازهای انتهای چسبندهٔ دو قطعهٔ دنا، آنزیم .......... با ایجاد پیوند .......... شکاف ستون قندـفسفات را می‌بندد.','لیگاز؛ فسفودی‌استر.', [('لیگاز',0.5),('فسفودی‌استر',0.5)])
final(12,7,'گزینش و تأیید سازه','essay','باکتری‌های دریافت‌کنندهٔ پلاسمید روی محیط دارای پادزیست انتخاب می‌شوند. چرا رشد یک کلنی برای ادعای «ژن هدف درست وارد شده و پروتئین هدف درست ساخته شده» کافی نیست؟ پاسخ را به نشانگر انتخابی و آزمون‌های بعدی مرتبط کنید.','رشد در محیط انتخابی وجود مقاومت مؤثر را پشتیبانی می‌کند. نشانگر مقاومت الزاماً توالی و محل درست ژن هدف یا بیان درست آن را نشان نمی‌دهد. باید وجود و صحت قطعهٔ هدف با بررسی دنا و تولید و کارکرد مناسب فرآورده با بررسی جداگانه تأیید شود؛ رشد فقط مرحلهٔ گزینش است.', [('رشد به‌عنوان شاهد مقاومت',0.5),('تفکیک نشانگر از صحت ژن هدف',0.5),('نیاز به بررسی جداگانهٔ دنا و فرآورده',0.5)])

final(12,8,'خوگیری','definition_comparison','خوگیری به یک صدای تکراری بی‌خطر را با ناتوانی عمومی در حرکت مقایسه کنید. پاسخ به یک محرک تازه چگونه در این مقایسه کمک می‌کند؟','در خوگیری، پاسخ به محرک تکراری کاهش می‌یابد، اما توان پاسخ‌دهی عمومی الزاماً از بین نمی‌رود. اگر جانور به محرک تازه گریز طبیعی نشان دهد، ناتوانی عمومی حرکتی توضیح مناسبی برای کاهش پاسخ به صدای قبلی نیست؛ این مشاهده با خوگیری سازگار است.', [('کاهش اختصاصی پاسخ بر اثر تکرار بی‌خطر',0.5),('حفظ توان پاسخ به محرک تازه و رد ناتوانی عمومی',0.5)])
final(12,8,'ارزش سازشی','matching','پرسش‌ها را به نوع بررسی وصل کنید: الف) کدام هورمون آغاز مهاجرت را تحریک می‌کند؟ ب) مهاجرت چگونه موفقیت تولیدمثلی را بیشتر می‌کند؟ پ) گیرندهٔ نوری چگونه طول روز را دریافت می‌کند؟ نوع‌ها: ۱) علت نزدیک/سازوکار، ۲) ارزش سازشی. یک نوع می‌تواند بیش از یک‌بار استفاده شود.','الف–۱؛ ب–۲؛ پ–۱. علت نزدیک چگونگی ایجاد رفتار و ارزش سازشی تأثیر رفتار بر بقا و تولیدمثل را بررسی می‌کند.', [('الف با علت نزدیک',0.5),('ب با ارزش سازشی',0.5),('پ با علت نزدیک',0.5)],promptParts=[{'id':'a','text':'هورمون آغاز مهاجرت'},{'id':'b','text':'افزایش موفقیت تولیدمثلی'},{'id':'c','text':'دریافت طول روز'}])
final(12,8,'هزینه و فایده','essay','پرنده‌ای می‌تواند خوراک کوچکِ نزدیک یا خوراک بزرگِ دور و سخت‌گشا را انتخاب کند. چرا اندازهٔ خوراک به‌تنهایی بهترین انتخاب را مشخص نمی‌کند؟ دست‌کم سه عامل مناسب برای مقایسه بنویسید.','باید انرژی قابل دریافت را در برابر هزینهٔ یافتن، رفتن و بازکردن خوراک سنجید. زمان لازم، انرژی مصرفی و خطر شکارشدن یا ازدست‌رفتن فرصت‌های دیگر نیز مهم‌اند. خوراک بزرگ‌تر می‌تواند سود خالص کمتری در واحد زمان داشته باشد؛ نتیجه به شرایط بستگی دارد.', [('انرژی دریافتی در مقایسه با انرژی هزینه‌شده',0.5),('زمان دستیابی/آماده‌سازی',0.5),('خطر یا هزینهٔ فرصت و رد نتیجه‌گیری صرفاً از اندازه',0.5)])
